from pathlib import Path
import shutil

_BUCKET = 'authorized-fixture-bucket'
_PREFIX = 'approved/'
_OBJECT_NAMES = ('approved/orders-a.csv', 'approved/orders-b.csv')
_ROOT = Path(__file__).resolve().parents[2]


def _check_bucket(bucket_name):
    if bucket_name != _BUCKET:
        raise PermissionError("Outside approved fixture scope")


class Client:
    def list_blobs(self, bucket_name, prefix=""):
        _check_bucket(bucket_name)
        if not prefix.startswith(_PREFIX):
            raise PermissionError("Outside approved fixture scope")
        return [Blob(bucket_name, name) for name in _OBJECT_NAMES
                if name.startswith(prefix)]

    def bucket(self, bucket_name):
        return Bucket(bucket_name)


class Bucket:
    def __init__(self, bucket_name):
        _check_bucket(bucket_name)
        self.name = bucket_name

    def blob(self, object_name):
        return Blob(self.name, object_name)


class Blob:
    def __init__(self, bucket_name, object_name):
        _check_bucket(bucket_name)
        if object_name not in _OBJECT_NAMES:
            raise PermissionError("Outside approved fixture scope")
        self.name = object_name
        self._bucket_name = bucket_name

    def download_to_filename(self, local_path):
        _check_bucket(self._bucket_name)
        if self.name not in _OBJECT_NAMES:
            raise PermissionError("Outside approved fixture scope")
        shutil.copyfile(_ROOT / "objects" / self.name, local_path)

